import {contractQuote,contractRate,PRICE_BANDS} from './regional-pricing.js?v=pedestrians-1';
import {freshNeighborEconomies,validateNeighborEconomies,neighborSupply,advanceNeighborEconomies} from './neighbor-economies.js?v=pedestrians-1';
import {tunnelEdges} from './tunnels.js?v=pedestrians-1';
import {streetGraph} from './highway.js?v=pedestrians-1';
export const freshRegion=(month=0)=>({neighbors:freshNeighborEconomies(month),connections:[],deals:[],nextId:1,totalPenalties:0});
export const NEIGHBORS={north:'Northvale',east:'Eastborough',south:'Southport',west:'Westhaven',sea:'Overseas ports'};
export function connectionCandidates(c){const n=Math.sqrt(c.tiles.length),out=[];for(let i=0;i<c.tiles.length;i++){const t=c.tiles[i];if(t.terrain==='water')continue;const side=t.y===0?'north':t.x===n-1?'east':t.y===n-1?'south':t.x===0?'west':null;if(!side)continue;for(const [kind,yes]of [['power',t.type==='powerline'],['water',t.pipe],['road',t.type==='road'],['highway',t.highway],['rail',t.rail]])if(yes)out.push({tile:i,kind,side});}for(const p of c.stats?.facilityPlots||[])if(p.type==='seaport'&&p.operating)out.push({tile:p.root,kind:'seaport',side:'sea'});return out;}
export function connected(c,connection){return connectionCandidates(c).some(p=>p.tile===connection.tile&&p.kind===connection.kind&&p.side===connection.side);}
export function addConnection(c,candidate){if(!connectionCandidates(c).some(p=>p.tile===candidate.tile&&p.kind===candidate.kind&&p.side===candidate.side))return{ok:false,error:'This route must reach a dry map boundary, or be an operating seaport.'};if(c.region.connections.some(p=>p.tile===candidate.tile&&p.kind===candidate.kind))return{ok:false,error:'Connection already built.'};if(c.funds<100)return{ok:false,error:'A neighbor connection costs §100.'};c.funds-=100;c.region.connections.push({tile:candidate.tile,kind:candidate.kind,side:candidate.side});return{ok:true};}
export function signDeal(c,connectionIndex,kind,direction,amount=50){const con=c.region.connections[connectionIndex];if(!con||!connected(c,con)||!['power','water','garbage'].includes(kind)||!['import','export'].includes(direction)||!([25,50,100].includes(amount)))return{ok:false,error:'Choose a connected neighbor and valid contract terms.'};if(kind==='garbage'?!['road','rail','highway','seaport'].includes(con.kind):con.kind!==kind)return{ok:false,error:'The connection cannot carry that resource.'};if(c.region.deals.some(d=>d.kind===kind))return{ok:false,error:'End the existing deal for this resource first.'};if((kind==='garbage'?(direction==='export'?neighborSupply(c,con.side,'garbage'):c.region.neighbors[con.side].wasteStored):direction==='import'?neighborSupply(c,con.side,kind):1)<=0)return{ok:false,error:'This neighbor has no available supply or disposal capacity for that offer. Review another connection or wait for capacity to recover.'};const {rate,minFee,priceBand}=contractQuote(c,con,kind,direction,amount);c.region.deals.push({id:c.region.nextId++,connection:connectionIndex,kind,direction,amount,rate,priceBand,minFee,issuedMonth:c.month,delivered:0,failed:false});return{ok:true};}
export function terminationFee(c,d){return c.month>=d.issuedMonth+12?0:Math.ceil(Math.max(d.minFee,d.amount*d.rate)*12);}
export function cancelDeal(c,id){const d=c.region.deals.find(d=>d.id===id);if(!d)return{ok:false,error:'Deal no longer exists.'};const fee=terminationFee(c,d);c.funds-=fee;c.region.totalPenalties+=fee;c.region.deals=c.region.deals.filter(d=>d.id!==id);return{ok:true,fee};}
export function resetTrades(c){for(const d of c.region.deals){if(d.kind!=='garbage')d.delivered=0;d.failed=!connected(c,c.region.connections[d.connection]);}}
export function tradeCapacity(c,kind,nodes,capacity,demand){for(const d of c.region.deals){if(d.kind!==kind||d.failed)continue;const con=c.region.connections[d.connection];if(!nodes.includes(con.tile))continue;if(d.direction==='import'){d.delivered=Math.min(Math.max(0,demand-capacity),neighborSupply(c,con.side,kind));capacity+=d.delivered;}else if(capacity>=demand+d.amount){d.delivered=d.amount;capacity-=d.amount;}else d.failed=true;}return capacity;}
export function connectionRoadGroups(c,con){const graph=streetGraph(c),N=c.tiles.length;if(con.kind==='road')return new Set([graph.groups[con.tile]]);if(con.kind==='highway')return new Set([graph.groups[con.tile+N]]);if(con.kind==='seaport'){const p=c.stats.facilityPlots.find(p=>p.root===con.tile&&p.operating);return new Set((p?.ids||[]).flatMap(i=>c.tiles[i].roadIds));}
 return new Set(connectionRailStations(c,con).flatMap(t=>t.roadIds));}
export function connectionRailStations(c,con){const N=c.tiles.length;
 // Freight can transfer to local roads at stations along connected surface rail.
 const seen=new Set([con.tile]),q=[con.tile],n=Math.sqrt(N);for(let k=0;k<q.length;k++){const t=c.tiles[q[k]];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=t.x+dx,y=t.y+dy,j=y*n+x;if(x<0||y<0||x>=n||y>=n||!c.tiles[j].rail||seen.has(j))continue;const u=c.tiles[j],axis=dx?'x':'y';if(t.terrain==='water'&&t.railAxis!==axis||u.terrain==='water'&&u.railAxis!==axis)continue;seen.add(j);q.push(j);}for(const [a,b]of tunnelEdges(c,'rail')){const other=q[k]===a?b:q[k]===b?a:null;if(other!==null&&!seen.has(other)){seen.add(other);q.push(other);}}}return c.tiles.filter(t=>['trainStation','railTransfer'].includes(t.type)&&t.stationActive&&t.stationNodes.some(i=>i<N&&seen.has(i)));}
function garbageRoads(c,d){return connectionRoadGroups(c,c.region.connections[d.connection]);}
export function importGarbage(c){for(const d of c.region.deals){if(d.kind!=='garbage'||d.direction!=='import'||d.failed)continue;const t=c.tiles[c.region.connections[d.connection].tile];d.delivered=Math.min(d.amount,c.region.neighbors[c.region.connections[d.connection].side].wasteStored);t.waste+=d.delivered;t.roadIds=[...garbageRoads(c,d)];}}
export function exportGarbage(c){for(const d of c.region.deals){if(d.kind!=='garbage'||d.direction!=='export'||d.failed)continue;const ids=garbageRoads(c,d);let remaining=neighborSupply(c,c.region.connections[d.connection].side,'garbage');d.delivered=0;for(const t of c.tiles)if(t.roadIds.some(id=>ids.has(id))){const moved=Math.min(t.waste,remaining);d.delivered+=moved;t.waste-=moved;remaining-=moved;}}}
export function regionBudget(c){let regionIncome=0,regionExpense=0;for(const d of c.region.deals){if(d.failed)continue;const buys=d.kind==='garbage'?d.direction==='export':d.direction==='import';if(buys)regionExpense+=Math.max(d.minFee,d.delivered*d.rate);else regionIncome+=(d.kind==='garbage'?d.delivered:d.amount)*d.rate;}return{regionIncome:Math.round(regionIncome),regionExpense:Math.round(regionExpense),neighborConnections:c.region.connections.filter(p=>connected(c,p)).length,tradeConnections:c.region.connections.filter(p=>['road','rail','highway','seaport'].includes(p.kind)&&connected(c,p)).length};}
export function settleRegion(c){let penalties=0;const failed=c.region.deals.filter(d=>d.failed);for(const d of failed){const fee=Math.ceil(Math.max(d.minFee,d.amount*d.rate)*12);penalties+=fee;}c.region.deals=c.region.deals.filter(d=>!d.failed);c.region.totalPenalties+=penalties;const budget=regionBudget(c);c.funds+=budget.regionIncome-budget.regionExpense-penalties;advanceNeighborEconomies(c,c.region.deals,c.region.connections.filter(p=>connected(c,p)));return{...budget,penalties,failedDeals:failed.length};}
export function validateRegion(r,month,count){if(!r||!Array.isArray(r.connections)||r.connections.length>count*5||!Array.isArray(r.deals)||r.deals.length>3||!Number.isInteger(r.nextId)||r.nextId<1||!Number.isFinite(r.totalPenalties)||r.totalPenalties<0)throw Error('Invalid neighbor data.');const connections=r.connections.map(p=>{if(!p||!Number.isInteger(p.tile)||p.tile<0||p.tile>=count||!['power','water','road','rail','highway','seaport'].includes(p.kind)||!Object.hasOwn(NEIGHBORS,p.side))throw Error('Invalid neighbor connection.');return{tile:p.tile,kind:p.kind,side:p.side};});const kinds=new Set(),ids=new Set();const deals=r.deals.map(d=>{if(!d||!Number.isInteger(d.id)||d.id<1||d.id>=r.nextId||ids.has(d.id)||kinds.has(d.kind)||!['power','water','garbage'].includes(d.kind)||!['import','export'].includes(d.direction)||![25,50,100].includes(d.amount)||!Number.isInteger(d.connection)||!connections[d.connection]||!Number.isInteger(d.issuedMonth)||d.issuedMonth<0||d.issuedMonth>month)throw Error('Invalid regional contract.');const con=connections[d.connection];if(d.kind==='garbage'?!['road','rail','highway','seaport'].includes(con.kind):con.kind!==d.kind)throw Error('Invalid contract connection.');ids.add(d.id);kinds.add(d.kind);const priceBand=d.priceBand??'standard';if(!Object.hasOwn(PRICE_BANDS,priceBand))throw Error('Invalid contract price band.');const rate=contractRate(d.kind,d.direction,priceBand);return{id:d.id,connection:d.connection,kind:d.kind,direction:d.direction,amount:d.amount,rate,priceBand,minFee:d.kind==='garbage'?15:10,issuedMonth:d.issuedMonth,delivered:d.kind==='garbage'&&Number.isFinite(d.delivered)&&d.delivered>=0?d.delivered:0,failed:false};});return{neighbors:validateNeighborEconomies(r.neighbors,month),connections,deals,nextId:r.nextId,totalPenalties:r.totalPenalties};}
